import {fromPartial} from '@total-typescript/shoehorn';
import {getActiveDocContext} from '../docsClientUtils';
import type {GlobalPluginData, GlobalVersion, GlobalDoc} from '../index';

function globalVersion(partial: Partial<GlobalVersion>): GlobalVersion {
  return fromPartial<GlobalVersion>(partial);
}
function globalDoc(partial: Partial<GlobalDoc>): GlobalDoc {
  return fromPartial<GlobalDoc>(partial);
}

// https://github.com/facebook/docusaurus/issues/10309
describe('current version with path /', () => {
  const current = globalVersion({
    name: 'current',
    label: 'Current',
    path: '/docs',
    isLast: false,
    docs: [globalDoc({id: 'doc1', path: '/docs/'})],
  });
  const v012 = globalVersion({
    name: 'v0.1.2',
    label: 'v0.1.2',
    path: '/docs/v0.1.2',
    docs: [globalDoc({id: 'doc1', path: '/docs/v0.1.2/'})],
  });
  const v020 = globalVersion({
    name: 'v0.2.0',
    label: 'v0.2.0',
    path: '/docs/v0.2.0',
    isLast: true,
    docs: [globalDoc({id: 'doc1', path: '/docs/v0.2.0/'})],
  });

  const data: GlobalPluginData = fromPartial({
    path: '/docs',
    versions: [current, v012, v020],
    breadcrumbs: true,
  });

  it('resolves active version on current version home', () => {
    expect(getActiveDocContext(data, '/docs').activeVersion?.name).toBe(
      'current',
    );
  });
  it('resolves active version on v0.1.2', () => {
    expect(getActiveDocContext(data, '/docs/v0.1.2').activeVersion?.name).toBe(
      'v0.1.2',
    );
    expect(
      getActiveDocContext(data, '/docs/v0.1.2/someDoc').activeVersion?.name,
    ).toBe('v0.1.2');
  });
  it('resolves active version on v0.2.0', () => {
    expect(getActiveDocContext(data, '/docs/v0.2.0').activeVersion?.name).toBe(
      'v0.2.0',
    );
    expect(
      getActiveDocContext(data, '/docs/v0.2.0/someDoc').activeVersion?.name,
    ).toBe('v0.2.0');
  });
});
